    cell.font = { bold: true, color: { argb: 'FF0D1117' }, size: 11 };
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FF00FFA3' },
    };
    cell.alignment = { horizontal: 'center', vertical: 'middle' };
    cell.border = {
      bottom: { style: 'thin', color: { argb: 'FF3D4450' } },
    };
  });

  // ── Data Rows ──
